mapper.select:
SELECT DISTINCT P.PROJECTID,P.PRJOECTNAME,P.PROJECTCODE,P.PROJECTSOURCE,P.STATUS, P.STARTDATE,P.ENDDATE,P.COSTS,TS.STAFFID,TS.REALNAME,P.EXAMINETYPE,(ENDDATE-STARTDATE)+1 DAYS LEFT JOIN TBL_NBSJ_PRO_TEAM T ON P.PROJECTID = T.PROJECTID LEFT JOIN TBL_NBSJ_TEAMSTAFF TNS ON T.TEAMID = TNS.TEAMID LEFT JOIN TBL_STAFF TS ON P.PMID = TS.STAFFID
and P.STATUS != 4
and P.orgId = #{re.orgId}
AND (TS.STAFFID = #{re.staffId} OR TS.STAFFID IS NULL)
AND P.PMID = #{re.pmId}
and P.PRJOECTNAME like concat(concat('%',#{re.prjoectName}),'%')
and P.PROJECTSOURCE like concat(concat('%',#{re.projectSource}),'%')
AND P.STARTDATE >= #{projectStartDate}
AND P.STARTDATE <= #{projectEndDate}
ORDER BY P.PROJECTID DESC

SELECT DISTINCT TNA.*,TS.REALNAME,TAS.REALNAME auditStaffName,TNA.orgIdNames auditOrgName FROM TBL_NBSJ_PROJECT TNA LEFT JOIN TBL_NBSJ_PRO_TEAM T ON TNA.PROJECTID = T.PROJECTID LEFT JOIN TBL_NBSJ_TEAMSTAFF TNS ON T.TEAMID = TNS.TEAMID LEFT JOIN TBL_STAFF TS ON TNA.PMID = TS.STAFFID LEFT JOIN TBL_STAFF TAS ON TNA.AUDITSTAFFID = TAS.STAFFID LEFT JOIN TBL_ORGANIZATION TD ON TNA.AUDITORGID = TD.ORGID
TNA.examineType= 6
AND TNA.ORGID = #{re.orgId} or (TNS.STAFFID = #{re.staffId} OR TNA.CREATESTAFFID = #{re.staffId} or OR TNA.PMID =#{re.staffId})
AND (TNS.STAFFID = #{re.staffId} OR TNA.CREATESTAFFID = #{re.staffId} OR TNA.PMID = #{re.staffId})
AND TNA.STATUS = #{re.status}
AND P.PMID = #{re.pmId}
and P.PRJOECTNAME like concat(concat('%',#{re.prjoectName}),'%')
and P.PROJECTSOURCE like concat(concat('%',#{re.projectSource}),'%')
AND P.STARTDATE >= #{projectStartDate}
AND P.STARTDATE <= #{projectEndDate}
ORDER BY P.PROJECTID DESC
